/* Forma v2. Local, explicitly labelled portfolio demo; no server authentication. */
(function(){
'use strict';
const C=window.FormaCore,F=window.FormaFiles,$=s=>document.querySelector(s);
const app=$('#app'),dialog=$('#dialog');
const icons={search:'<circle cx="10.8" cy="10.8" r="7.3"/><path d="m16.3 16.3 4.7 4.7"/>',heart:'<path class="heart-icon" d="M20.8 4.9c-2.1-2.2-5.6-1.9-8.8 1.4-3.2-3.3-6.7-3.6-8.8-1.4-2.8 2.9-1.4 7 1.1 9.7L12 22l7.7-7.4c2.5-2.7 3.9-6.8 1.1-9.7Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 10h18"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',back:'<path d="m15 5-7 7 7 7"/>',arrow:'<path d="m9 5 7 7-7 7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',pin:'<path d="M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',check:'<path d="m5 12 4 4L20 5"/>',camera:'<path d="M8 5 9 3h6l1 2h4a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z"/><circle cx="12" cy="12" r="4"/>',file:'<path d="M14 2H5v20h14V7Z"/><path d="M14 2v6h5M8 12h8m-8 4h6"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7a3 3 0 0 0-4-4L5 15Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 16h12l1-16M10 10v8m4-8v8"/>',plus:'<path d="M12 4v16M4 12h16"/>',filter:'<path d="M3 6h7m4 0h7M3 12h2m4 0h12M3 18h12m4 0h2"/><circle cx="12" cy="6" r="2"/><circle cx="7" cy="12" r="2"/><circle cx="17" cy="18" r="2"/>',nails:'<path d="M9 8V2h6v6M8 8h8l2 14H6ZM11 2v6m2-6v6"/>',hair:'<path d="M6 22c-2-6 0-10 2-12 3-3 0-5 4-8 5 1 7 5 6 9-2 3-4 5-3 11M10 22c-2-5 5-9 4-14M3 16c-1-6 2-11 5-12"/>',brows:'<path d="M2 15C8 7 15 5 22 9M4 15c5-4 10-5 15-5"/>',makeup:'<path d="m4 20 4-1 8-10-3-3L5 16ZM13 6l2-3c4-2 7 1 5 5l-4 1M3 22l3-3"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V3h8v4M3 12h18m-9-2v5"/>',shield:'<path d="M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6Z"/><path d="m8 12 3 3 5-6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function read(key,fallback,storage=localStorage){try{const r=JSON.parse(storage.getItem(key));return r??fallback}catch{return fallback}}
const clone=v=>JSON.parse(JSON.stringify(v));
const seeds=clone(window.FORMA_SEED);
let savedState=read('forma-state-v2',null);
let db=savedState&&Array.isArray(savedState.masters)&&savedState.masters.length? savedState:{version:2,masters:seeds,bookings:[],saved:[],savedWorks:[],reviews:[],client:{name:''}};
for(const key of ['bookings','saved','savedWorks','reviews'])if(!Array.isArray(db[key]))db[key]=[];
if(!db.client||typeof db.client!=='object')db.client={name:''};
if(!savedState){const oldSaved=read('forma-saved',[]),oldBookings=read('forma-bookings',[]);db.saved=Array.isArray(oldSaved)?oldSaved.filter(id=>seeds.some(m=>m.id===id)):[];db.bookings=Array.isArray(oldBookings)?oldBookings.filter(b=>b&&seeds.some(m=>m.id===b.master)).map(b=>{const m=seeds.find(m=>m.id===b.master),s=m.services[0];return {...b,serviceId:s.id,serviceName:s.name,price:s.price,duration:s.duration,status:b.status==='cancelled'?'cancelled':'pending',createdAt:new Date(b.id||Date.now()).toISOString()}}):[];}
let draft=read('forma-draft-v2',{}),contact=read('forma-contact',{},sessionStorage),studioId=Number(read('forma-studio-master',1));
if(!db.masters.some(m=>m.id===studioId))studioId=db.masters[0].id;
let filters={cat:'',budget:0,area:'',search:'',sort:'recommended'},savedTab='masters',bookingTab='active',fileURLs=new Map(),route='',currentMasterId=null;
const categoryDefs=[{id:'nails',name:'Ногти',icon:'nails'},{id:'allhair',name:'Волосы',icon:'hair'},{id:'browlash',name:'Брови и ресницы',icon:'brows'},{id:'makeup',name:'Макияж',icon:'makeup'}];
const serviceCats=[['nails','Маникюр'],['hair','Окрашивание'],['cut','Стрижка'],['brows','Брови'],['lashes','Ресницы'],['makeup','Макияж']];
const areas=['Центр','Юго-Западный','Северо-Западный'];
const statusNames={pending:'Ждём ответа',proposal:'Нужно ваше решение',confirmed:'Запись подтверждена',completed:'Визит завершён',cancelled:'Заявка отменена',declined:'Мастер не сможет принять'};
function persist(){localStorage.setItem('forma-state-v2',JSON.stringify(db))}
function commit(fn){const old=clone(db);try{fn(db);persist()}catch(e){db=old;throw Error('Изменения не сохранены. Возможно, закончилось место в браузере. Попробуйте ещё раз.')}}
try{persist()}catch{}
function saveDraft(){const clean={...draft};delete clean.phone;delete clean.consent;try{localStorage.setItem('forma-draft-v2',JSON.stringify(clean))}catch{toast('Черновик не удалось сохранить в браузере')}}
function saveContact(){try{sessionStorage.setItem('forma-contact',JSON.stringify(contact))}catch{}}
function money(n){return Number(n||0).toLocaleString('ru-RU')+' ₽'}
function dateText(v,options={day:'numeric',month:'long'}){return C.validDate(v)?new Date(v+'T12:00:00').toLocaleDateString('ru-RU',options):'Дата не выбрана'}
function timeText(v){return v.time||({morning:'Утро, 09:00–12:00',day:'День, 12:00–17:00',evening:'После 17:00'})[v.period]||'Время не выбрано'}
function duration(n){const h=Math.floor(n/60),m=n%60;return `${h?h+' ч ':''}${m?m+' мин':''}`.trim()||'Уточните у мастера'}
function master(id){return db.masters.find(m=>m.id===Number(id))}
function service(m,id){return m?.services.find(s=>s.id===id&&s.active!==false)}
function allWorks(){return db.masters.filter(m=>m.active!==false).flatMap(m=>m.works.map(w=>({...w,masterId:m.id,masterName:m.name})))}
function work(id){return allWorks().find(w=>w.id===id)}
function imageSrc(value,fallback='nails'){if(value?.startsWith('file-'))return fileURLs.get(value)||'assets/'+fallback+'.jpg';if(/^[a-zA-Z0-9_-]+$/.test(value||''))return 'assets/'+value+'.jpg';return 'assets/'+fallback+'.jpg'}
function workImage(w){return imageSrc(w?.fileId||w?.image,'nails')}
function refImage(){if(draft.referenceFile)return imageSrc(draft.referenceFile);const w=work(draft.referenceWork);return w?workImage(w):null}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500)}
function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function action(name,label,cls='primary',extra=''){return `<button type="button" class="${cls}" data-action="${name}" ${extra}>${label}</button>`}
function pageTitle(title,subtitle='',back='home',extra=''){return `<div class="page-heading">${back!==null?`<a class="back-button" href="#${back}" aria-label="Назад">${icon('back')}</a>`:''}<div class="heading-copy"><h1>${esc(title)}</h1>${subtitle?`<p class="muted">${esc(subtitle)}</p>`:''}</div>${extra}</div>`}
function hint(text){return `<div class="hint">${icon('info')}<span>${text}</span></div>`}
function notice(text,cls='demo'){return `<div class="notice ${cls}">${text}</div>`}
function errorBox(){return '<div class="form-error" role="alert" id="formError" tabindex="-1"></div>'}
function formError(message){const el=$('#formError');if(el){el.textContent=message;el.focus();el.scrollIntoView({block:'center',behavior:'smooth'})}else toast(message)}
function empty(title,text,link='home',label='Найти мастера',ico='search'){return `<section class="empty-state"><div class="empty-icon">${icon(ico)}</div><h2>${esc(title)}</h2><p>${esc(text)}</p><a class="primary" href="#${link}">${esc(label)}</a></section>`}
function statusBadge(b){return `<span class="status-label ${esc(b.status)}">${icon(b.status==='pending'?'clock':b.status==='confirmed'?'check':'info')}${esc(statusNames[b.status]||'Заявка')}</span>`}
function showDialog(title,body,buttons=''){ $('#dialogBody').innerHTML=`<div class="dialog-header"><h2 id="dialogTitle">${esc(title)}</h2></div>${body}${buttons?`<div class="dialog-buttons">${buttons}</div>`:''}`;if(!dialog.open)dialog.showModal(); }
function confirmDialog(title,text,callback,label='Подтвердить'){showDialog(title,`<p class="dialog-body-copy">${esc(text)}</p>`,`<button class="primary" id="confirmAction">${esc(label)}</button><button class="secondary" data-action="close-dialog">Вернуться</button>`);$('#confirmAction').onclick=async()=>{const btn=$('#confirmAction');btn.disabled=true;try{await callback();dialog.close()}catch(e){toast(e.message);btn.disabled=false}}}
function favoriteMaster(id,button){commit(()=>{db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id]});const yes=db.saved.includes(id);toast(yes?'Мастер сохранён':'Мастер убран из избранного');if(route==='saved')render(false);else if(button){button.classList.toggle('active',yes);button.setAttribute('aria-pressed',String(yes));button.setAttribute('aria-label',(yes?'Убрать из избранного: ':'Сохранить мастера: ')+master(id)?.name)}}
function favoriteWork(id,button){commit(()=>{db.savedWorks=db.savedWorks.includes(id)?db.savedWorks.filter(x=>x!==id):[...db.savedWorks,id]});const yes=db.savedWorks.includes(id);toast(yes?'Работа сохранена':'Работа убрана из избранного');if(route==='saved')render(false);else if(button){button.classList.toggle('active',yes);button.setAttribute('aria-pressed',String(yes))}}
function workTile(w){return `<article class="work-tile"><a href="#work/${encodeURIComponent(w.id)}" class="work-photo"><img src="${workImage(w)}" alt="${esc(w.title)}" loading="lazy"></a><button class="icon-button save-work ${db.savedWorks.includes(w.id)?'active':''}" data-action="save-work" data-id="${esc(w.id)}" aria-pressed="${db.savedWorks.includes(w.id)}" aria-label="Сохранить работу: ${esc(w.title)}">${icon('heart')}</button><h3><a href="#work/${encodeURIComponent(w.id)}">${esc(w.title)}</a></h3><span class="price-tag subtle">Эта работа — ${money(w.price)}</span><p class="muted">${esc(w.masterName||master(w.masterId)?.name||'')}</p></article>`}
function masterCard(m){const s=m.matchedServices?.[0]||m.services.find(s=>s.active!==false),w=m.works.find(w=>w.serviceId===s?.id)||m.works[0];if(!s)return '';return `<article class="master-card"><div class="cover"><a href="#master/${m.id}?service=${encodeURIComponent(s.id)}" aria-label="Работы мастера ${esc(m.name)}"><img src="${workImage(w)}" alt="${esc(w?.title||m.name)}" loading="lazy"></a><button class="icon-button ${db.saved.includes(m.id)?'active':''}" data-action="save-master" data-id="${m.id}" aria-pressed="${db.saved.includes(m.id)}" aria-label="${db.saved.includes(m.id)?'Убрать из избранного':'Сохранить мастера'}: ${esc(m.name)}">${icon('heart')}</button></div><div class="card-body"><div class="person"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><h3><a href="#master/${m.id}?service=${encodeURIComponent(s.id)}">${esc(m.name)}</a></h3><p>${esc(m.role)}</p></div></div><div class="rating"><span class="star">★</span><strong>${esc(m.rating)}</strong><span class="muted">· ${m.reviews} отзывов · ${esc(m.area)}</span></div><div class="card-price"><span>${esc(s.name)}</span><span class="price-tag">${money(s.price)}</span></div>${s.pricing==='estimate'?'<p class="small muted" style="margin:-5px 0 16px">Предварительно · '+esc(s.description)+'</p>':''}<a class="primary" href="#master/${m.id}?service=${encodeURIComponent(s.id)}">Посмотреть мастера</a></div></article>`}
function home(){const works=allWorks();const requestExists=draft.masterId&&master(draft.masterId)&&draft.date;app.innerHTML=`${requestExists?`<div class="home-draft"><div><strong>У вас есть черновик</strong><p>Заявка к ${esc(master(draft.masterId).name)}</p></div><a class="link blue" href="#booking/${draft.masterId}">Продолжить</a></div>`:''}<div class="home-columns"><div class="home-intro"><form id="homeSearch" role="search"><div class="search-field">${icon('search')}<input type="search" name="search" placeholder="Услуга или мастер" aria-label="Услуга или мастер" enterkeyhint="search"><button class="sr-only" type="submit">Найти</button></div></form><section class="category-grid" aria-label="Выберите услугу">${categoryDefs.map(c=>`<button class="category-tile" data-action="category" data-id="${c.id}">${icon(c.icon)}${c.name}</button>`).join('')}</section><section class="concierge-entry"><img src="assets/nails.jpg" alt="Пример маникюра"><div class="entry-copy"><h2>Хочу похожий результат</h2><p>Укажите бюджет, район и время — подберём варианты.</p><a class="primary" href="#guide">Собрать визит</a><a class="link" href="#guide?withoutPhoto=1">Можно без фото</a></div></section><div class="demo-strip">Демонстрационный проект · Ставрополь</div></div><section class="section"><div class="section-title"><h2>Работы рядом</h2><a class="link" href="#catalog">Все мастера ${icon('arrow')}</a></div><div class="work-grid">${works.slice(0,4).map(workTile).join('')}</div></section></div><section class="home-continued"><div class="section-title"><h2>Выбирайте человека, которому доверитесь</h2></div><div class="master-grid">${C.filterMasters(db.masters).slice(0,3).map(masterCard).join('')}</div></section>`}
function searchForm(){return `<form id="catalogSearch" role="search"><div class="search-field">${icon('search')}<input type="search" name="search" value="${esc(filters.search)}" placeholder="Услуга или мастер" aria-label="Услуга или мастер" enterkeyhint="search"><button type="submit" class="sr-only">Найти</button></div></form>`}
function catalog(){const label=categoryDefs.find(c=>c.id===filters.cat)?.name||serviceCats.find(c=>c[0]===filters.cat)?.[1]||'Найдите своего мастера';app.innerHTML=pageTitle(label,'Ставрополь')+searchForm()+`<div class="chips-scroll" aria-label="Услуги"><button class="chip ${!filters.cat?'selected':''}" data-action="catalog-cat" data-id="">Все услуги</button>${serviceCats.map(([id,label])=>`<button class="chip ${filters.cat===id?'selected':''}" data-action="catalog-cat" data-id="${id}">${label}</button>`).join('')}</div><div class="catalog-controls">${action('filters',`${icon('filter')} Фильтры`,'chip')}<select id="catalogBudget" class="filter-select ${filters.budget?'selected':''}" aria-label="Бюджет"><option value="0">Цена: любая</option>${[1500,2500,3500,6000,10000].map(n=>`<option value="${n}" ${Number(filters.budget)===n?'selected':''}>До ${money(n)}</option>`).join('')}</select><select id="catalogArea" class="filter-select ${filters.area?'selected':''}" aria-label="Район"><option value="">Район: любой</option>${areas.map(a=>`<option ${a===filters.area?'selected':''}>${a}</option>`).join('')}</select>${filters.cat||filters.search||filters.budget||filters.area?action('reset-filters','Сбросить','link'):''}</div><div class="catalog-summary"><span id="resultCount" aria-live="polite"></span><select id="catalogSort" aria-label="Сортировка"><option value="recommended">Рекомендуемые</option><option value="price" ${filters.sort==='price'?'selected':''}>Сначала дешевле</option><option value="rating" ${filters.sort==='rating'?'selected':''}>По оценке</option></select></div><div class="master-grid" id="catalogResults"></div>`;catalogResults()}
function catalogResults(){const list=C.filterMasters(db.masters,filters);$('#resultCount').textContent=`${list.length} ${list.length===1?'мастер':'мастеров'}`;$('#catalogResults').innerHTML=list.length?list.map(masterCard).join(''):`<div style="grid-column:1/-1">${empty('По этим условиям мастеров нет','Попробуйте убрать ограничение цены или изменить район.','catalog','Сбросить фильтры')}</div>`;if(!list.length)$('#catalogResults .primary').onclick=e=>{e.preventDefault();filters={cat:'',budget:0,area:'',search:'',sort:'recommended'};catalog()}}
function filtersDialog(){showDialog('Условия поиска',`<form id="filtersForm"><div class="field"><label for="filterPrice">Бюджет до, ₽</label><input id="filterPrice" name="budget" type="number" min="0" max="1000000" value="${Number(filters.budget)||''}" placeholder="Любой бюджет"></div><div class="field"><label for="filterArea">Где удобно</label><select id="filterArea" name="area"><option value="">Весь город</option>${areas.map(a=>`<option ${filters.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="field"><label for="filterCat">Услуга</label><select id="filterCat" name="cat"><option value="">Все услуги</option>${serviceCats.map(([id,label])=>`<option value="${id}" ${filters.cat===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="dialog-buttons"><button class="primary" type="submit">Показать мастеров</button>${action('reset-filters','Сбросить','secondary')}</div></form>`)}
function savedPage(){app.innerHTML=pageTitle('Избранное','Мастера и работы, которые вам понравились','home')+`<div class="segmented" style="margin-bottom:24px"><button data-action="saved-tab" data-id="masters" class="${savedTab==='masters'?'active':''}">Мастера · ${db.saved.length}</button><button data-action="saved-tab" data-id="works" class="${savedTab==='works'?'active':''}">Работы · ${db.savedWorks.length}</button></div>`;if(savedTab==='masters'){const list=C.filterMasters(db.masters,{ids:db.saved});app.innerHTML+=list.length?`<div class="master-grid">${list.map(masterCard).join('')}</div>`:empty('Сохраните тех, кто понравился','Нажмите на сердечко у мастера — его профиль появится здесь.','catalog','Найти мастера','heart')}else{const list=allWorks().filter(w=>db.savedWorks.includes(w.id));app.innerHTML+=list.length?`<div class="work-grid">${list.map(workTile).join('')}</div>`:empty('Сохраните понравившиеся работы','Нажмите на сердечко у фотографии, чтобы вернуться к ней позже.','home','Смотреть работы','heart')}}
function publicDocuments(m){const docs=m.documents.filter(d=>d.status==='reviewed');return docs.length?docs.map(d=>docRow(m,d,false)).join(''):'<p class="muted small">Мастер пока не опубликовал документы.</p>'}
function docRow(m,d,manage=false){const labels={uploaded:'Загружен мастером',reviewed:'Демо: проверен модератором',rejected:'Нужны исправления'};return `<article class="doc-row"><div class="doc-icon">${icon('file')}</div><div class="doc-copy"><strong>${esc(d.title)}</strong><p>${esc(d.kind)} · ${esc(d.name)} · ${(d.size/1024/1024).toFixed(1)} МБ</p><span class="doc-state ${d.status==='reviewed'?'reviewed':''}">${esc(labels[d.status]||labels.uploaded)}</span>${d.reason?`<p>${esc(d.reason)}</p>`:''}${d.reviewedAt?`<p>Демонстрационная отметка от ${dateText(d.reviewedAt.slice(0,10))}. Реальная подлинность не проверялась.</p>`:''}<div class="button-row">${action('open-doc','Открыть файл','link',`data-master="${m.id}" data-id="${esc(d.id)}"`)}${manage?action('delete-doc','Удалить','link danger',`data-master="${m.id}" data-id="${esc(d.id)}"`):''}</div></div></article>`}
function profile(id,params){const m=master(id);if(!m||m.active===false){app.innerHTML=empty('Профиль недоступен','Мастер сейчас не принимает заявки.','catalog','Другие мастера');return}currentMasterId=m.id;const chosen=service(m,params.get('service'))||service(m,draft.masterId===m.id?draft.serviceId:'')||m.services.find(s=>s.active!==false),reviews=db.reviews.filter(r=>r.master===m.id);app.innerHTML=pageTitle('', '', 'catalog',`<button class="icon-button ${db.saved.includes(m.id)?'active':''}" data-action="save-master" data-id="${m.id}" aria-label="Сохранить мастера: ${esc(m.name)}" aria-pressed="${db.saved.includes(m.id)}">${icon('heart')}</button>`)+`<div class="profile-top"><img class="profile-cover" src="${workImage(m.works.find(w=>w.serviceId===chosen?.id)||m.works[0])}" alt="Пример работы ${esc(m.name)}"><section class="profile-summary"><div class="profile-heading"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><h1>${esc(m.name)}</h1><p>${esc(m.role)}</p><div class="rating"><span class="star">★</span><strong>${esc(m.rating)}</strong><span class="muted">· ${m.reviews} отзывов</span></div></div></div><div class="profile-facts"><span>${esc(m.area)} · Ставрополь</span><span>Опыт ${esc(m.experience)}</span></div><p class="profile-intro">${esc(m.text)}</p>${chosen?`<div class="card-price"><span>${esc(chosen.name)}</span><span class="price-tag">${money(chosen.price)}</span></div>${chosen.pricing==='estimate'?'<p class="small muted">Предварительная стоимость · '+esc(chosen.description)+'</p>':''}<div class="profile-action">${action('start-booking','Выбрать время','primary',`data-master="${m.id}" data-service="${esc(chosen.id)}"`)}</div>`:''}</section></div><section class="profile-content"><nav class="anchor-tabs" aria-label="Разделы профиля"><a href="#" data-section="worksSection">Работы</a><a href="#" data-section="servicesSection">Услуги</a><a href="#" data-section="reviewsSection">Отзывы</a><a href="#" data-section="documentsSection">О мастере</a></nav><section class="section" id="worksSection"><div class="section-title"><h2>Работы</h2><span class="small muted">${m.works.length}</span></div>${m.works.length?`<div class="work-grid">${m.works.map(w=>workTile({...w,masterId:m.id,masterName:m.name})).join('')}</div>`:'<p class="small muted">Мастер ещё не добавил работы.</p>'}</section><section class="section" id="servicesSection"><h2>Услуги и цены</h2>${m.services.filter(s=>s.active!==false).map(s=>`<article class="service-row"><div><h3>${esc(s.name)}</h3><p>${duration(s.duration)}${s.pricing==='estimate'?' · предварительная цена':''}</p><span class="price-tag">${money(s.price)}</span>${s.description?`<p style="margin-top:8px">${esc(s.description)}</p>`:''}</div>${action('start-booking','Выбрать','secondary',`data-master="${m.id}" data-service="${esc(s.id)}"`)}</article>`).join('')}</section><section class="section" id="reviewsSection"><h2>Отзывы</h2>${reviews.map(r=>`<article class="review"><div class="review-head"><strong>${esc(r.name)}</strong><span class="star">${'★'.repeat(r.rating)}</span></div><p>${esc(r.text)}</p><small>${esc(r.service)} · демовизит</small></article>`).join('')}<article class="review"><div class="review-head"><strong>Екатерина</strong><span class="star">★★★★★</span></div><p>Обсудили пожелания перед началом. Результат понравился, всё аккуратно.</p><small>Пример отзыва для демонстрации интерфейса</small></article></section><section class="section" id="documentsSection"><h2>Образование и документы</h2>${publicDocuments(m)}<p class="small muted" style="margin-top:16px">Отметка в этом учебном проекте демонстрирует процесс модерации. Она не подтверждает подлинность документа или качество услуги.</p><details><summary>Где принимает мастер</summary><p>Ставрополь, ${esc(m.address)} · ${esc(m.area)}.</p><p>Это демонстрационный адрес, он не является местом приёма указанного человека.</p></details><details><summary>Как устроена запись</summary><p>Вы отправляете пожелания, затем мастер предлагает точное время и цену. Запись подтверждается после вашего согласия. В этом демо всё происходит локально в одном браузере.</p></details></section></section>`;if(chosen)setSticky(action('start-booking',draft.masterId===m.id?'Продолжить запись':'Выбрать время','primary',`data-master="${m.id}" data-service="${esc(chosen.id)}"`),draft.masterId===m.id?'Ваши пожелания сохранены':'')}
function workPage(id){const w=work(id),m=w&&master(w.masterId);if(!w||!m){app.innerHTML=empty('Работа недоступна','Посмотрите другие работы мастеров.');return}app.innerHTML=pageTitle('Работа мастера','',`master/${m.id}`,`<button class="icon-button ${db.savedWorks.includes(w.id)?'active':''}" data-action="save-work" data-id="${esc(w.id)}" aria-label="Сохранить работу" aria-pressed="${db.savedWorks.includes(w.id)}">${icon('heart')}</button>`)+`<div class="work-detail"><section><img id="workDetailImage" class="work-detail-photo" src="${workImage(w)}" alt="${esc(w.title)}">${w.beforeFile?`<div class="comparison-controls">${action('work-photo','После','chip selected',`data-id="${esc(w.id)}" data-photo="after"`)}${action('work-photo','До','chip',`data-id="${esc(w.id)}" data-photo="before"`)}</div>`:''}<div class="demo-strip">${w.demo?'Иллюстративная фотография · пример работы':'Работа, добавленная в локальном демокабинете'}</div></section><section class="work-detail-info"><h1>${esc(w.title)}</h1><span class="price-tag">Эта работа — ${money(w.price)}</span><p class="muted">${duration(w.duration)}</p><p>${esc(w.description)}</p><p class="small muted">Стоимость похожей услуги мастер уточнит до подтверждения. Фото — ориентир, результат обсуждается индивидуально.</p><a class="person" href="#master/${m.id}"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><h3>${esc(m.name)}</h3><p>Профиль мастера</p></div>${icon('arrow')}</a><div class="button-row">${action('book-work','Хочу похожий результат','primary',`data-id="${esc(w.id)}"`)}<a class="secondary" href="#guide?work=${encodeURIComponent(w.id)}">Найти других мастеров</a></div></section></div>`;setSticky(action('book-work','Хочу похожий результат','primary',`data-id="${esc(w.id)}"`))}
function referenceBlock(){const img=refImage();return `<div class="reference-hero"><img data-reference-image src="${img||'assets/nails.jpg'}" alt="${img?'Ваш ориентир':'Пример результата для вдохновения'}"><div class="upload-reference"><label class="secondary" style="cursor:pointer">${icon('camera')} ${img?'Заменить фото':'Добавить фото'}<input type="file" id="referenceUpload" class="sr-only" accept="image/jpeg,image/png,image/webp"></label></div></div><div class="reference-caption"><span>${img?'Фото — ориентир':'Фото необязательно · сейчас показан пример'}</span>${img?action('remove-reference','Убрать фото','link'):''}</div>`}
function dayTimeFields(wish){const today=C.localDate(),tomorrow=C.addDays(today,1);const selected=wish.date||tomorrow;const days=Array.from({length:5},(_,i)=>C.addDays(today,i+1));return `<section class="date-time-section"><label for="wishDate">Желаемая дата</label><div class="day-grid">${days.map(d=>`<button type="button" class="day-option ${d===selected?'selected':''}" data-action="select-day" data-date="${d}" aria-pressed="${d===selected}"><span>${new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'short'})}</span><strong>${new Date(d+'T12:00:00').getDate()}</strong></button>`).join('')}</div><div class="date-custom"><label for="wishDate">Другая дата или выбранный день</label><input id="wishDate" name="date" type="date" min="${today}" value="${esc(selected)}" required></div></section><section class="date-time-section"><label>Желаемое время</label><input type="hidden" name="period" value="${esc(wish.period||'')}"><div class="time-options">${[['morning','Утро','09:00–12:00'],['day','День','12:00–17:00'],['evening','Вечер','17:00–21:00']].map(([id,label,hours])=>`<button type="button" class="time-option ${wish.period===id?'selected':''}" data-action="select-period" data-id="${id}" aria-pressed="${wish.period===id}">${label}<small>${hours}</small></button>`).join('')}</div>${action('select-period','Указать точное время','link',`data-id="exact"`)}<div class="exact-time" ${wish.period==='exact'||wish.time?'':'hidden'}><label for="exactTime" class="small muted">Желаемое начало визита</label><input id="exactTime" type="time" name="time" value="${esc(wish.time||'')}" ${wish.period==='exact'?'':'disabled'}></div></section>`}
function guide(params){if(params.get('work')){const w=work(params.get('work')),m=w&&master(w.masterId),s=m&&service(m,w.serviceId);if(w){draft.referenceWork=w.id;draft.referenceFile='';if(s)draft.cat=s.cat;saveDraft()}}if(params.get('withoutPhoto')){draft.referenceWork='';draft.referenceFile='';saveDraft()}app.innerHTML=pageTitle('Соберём ваш визит','', 'home')+`<div class="form-page"><form id="guideForm" data-draft="guide">${referenceBlock()}<div class="field"><label for="guideService">Услуга</label><select id="guideService" name="cat" required><option value="">Что хотите сделать?</option>${serviceCats.map(([id,label])=>`<option value="${id}" ${draft.cat===id?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="guideBudget">Бюджет до, ₽</label><input id="guideBudget" type="number" inputmode="numeric" min="1" max="1000000" name="budget" value="${esc(draft.budget||'')}" placeholder="Например, 3 000" required><p class="help">Покажем услуги в пределах этой суммы. Итог мастер уточнит до подтверждения.</p></div><div class="field"><label for="guideArea">Где удобно</label><select id="guideArea" name="area"><option value="">Любой район Ставрополя</option>${areas.map(a=>`<option ${draft.area===a?'selected':''}>${a}</option>`).join('')}</select></div>${dayTimeFields(draft)}${hint('Учтём услугу, бюджет, район и рабочие часы. Фото передаётся мастеру как ориентир: автоматического распознавания здесь нет.')}${errorBox()}<div class="form-actions"><button type="submit" class="primary">Найти мастеров</button></div></form><p class="demo-strip">Черновик сохраняется на этом устройстве.</p></div>`}
function collectDraft(form){const fd=new FormData(form);for(const [k,v]of fd){if(k==='phone'){contact.phone=String(v);continue}if(k==='consent')continue;draft[k]=String(v)}if(draft.period!=='exact')draft.time='';saveDraft();saveContact();return draft}
function shortlist(){if(!draft.cat||!draft.budget||C.validateWish(draft)){app.innerHTML=empty('Уточните пожелания','Укажите услугу, бюджет и удобное время — затем покажем варианты.','guide','Собрать визит');return}const list=C.filterMasters(db.masters,{cat:draft.cat,budget:draft.budget,area:draft.area,date:draft.date,period:draft.period,time:draft.time});app.innerHTML=pageTitle('Подходящие мастера','', 'guide')+`<div class="form-page"><div class="request-context"><span>${esc(serviceCats.find(c=>c[0]===draft.cat)?.[1]||'Услуга')} · <span class="price-tag subtle">До ${money(draft.budget)}</span> · ${esc(draft.area||'Весь город')}</span><a class="link" href="#guide">Изменить</a></div><div style="margin:18px 0">${hint(`${dateText(draft.date)}, ${esc(timeText(draft))} — пожелание`)}</div>${list.length?`<div class="selection-list">${list.map(m=>{const s=m.matchedServices[0],w=m.works.find(w=>w.serviceId===s.id)||m.works[0];return `<article class="shortlist-row"><a href="#master/${m.id}?service=${encodeURIComponent(s.id)}" aria-label="Работы ${esc(m.name)}"><img src="${workImage(w)}" alt="Пример работы ${esc(m.name)}"></a><div><a class="person" href="#master/${m.id}?service=${encodeURIComponent(s.id)}"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><h3>${esc(m.name)}</h3></div>${icon('arrow')}</a><span class="price-tag large">${money(s.price)}</span><div class="rating"><span class="star">★</span>${esc(m.rating)} · ${m.reviews} отзывов</div><p class="small muted">${esc(m.area)}</p><a href="#master/${m.id}?service=${encodeURIComponent(s.id)}" class="link">Работы и отзывы ${icon('arrow')}</a></div></article>`}).join('')}</div><div class="shortlist-footer notice">Подходят по услуге, бюджету, району и рабочим часам. Занятость и окончательное время подтвердит мастер.</div>`:empty('Точного совпадения пока нет','Попробуйте увеличить бюджет, выбрать другой район или день.','guide','Изменить пожелания')}<a class="link" href="#catalog">Посмотреть всех мастеров</a></div>`}
function startBooking(masterId,serviceId,workId){const m=master(masterId),s=service(m,serviceId)||m?.services.find(s=>s.active!==false);if(!m||!s||m.active===false)throw Error('Услуга сейчас недоступна');draft={...draft,masterId:m.id,serviceId:s.id,cat:s.cat};delete draft.editingId;if(workId){draft.referenceWork=workId;draft.referenceFile=''}saveDraft();go('booking/'+m.id)}
function bookingPage(id){const m=master(id),s=m&&service(m,draft.serviceId);if(!m||!s||m.active===false){app.innerHTML=empty('Выберите услугу','Возможно, мастер изменил прайс. Пожелания остались в черновике.','catalog','Найти мастера');return}draft.masterId=m.id;app.innerHTML=pageTitle('Когда вам удобно?','Шаг 1 из 2',`master/${m.id}?service=${encodeURIComponent(s.id)}`)+`<div class="form-page"><div class="request-preview"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><strong>${esc(m.name)}</strong><p>${esc(s.name)} · <span class="price-tag subtle">${money(s.price)}</span></p><p class="muted small">${duration(s.duration)}</p></div></div><form id="bookingWishForm" data-draft="booking">${dayTimeFields(draft)}<div class="field"><label for="bookingNote">Пожелания, необязательно</label><textarea name="note" id="bookingNote" maxlength="1000" placeholder="Например, хочу форму как на фотографии">${esc(draft.note||'')}</textarea></div>${refImage()?`<div class="review-reference"><img src="${refImage()}" alt="Ваш ориентир"><div><strong>Ваш ориентир</strong><p>Фото будет прикреплено к заявке.</p></div></div>`:''}${hint('Это желаемое время. Мастер предложит точное начало и стоимость. Вы сможете согласиться или выбрать другое.')}${errorBox()}<div class="form-actions"><button class="primary" type="submit">Проверить заявку</button></div></form></div>`}
function reviewPage(){const m=master(draft.masterId),s=m&&service(m,draft.serviceId);if(!m||!s||C.validateWish(draft)){app.innerHTML=empty('Проверьте время и услугу','Вернитесь к выбору времени. Черновик сохранён.',m?'booking/'+m.id:'guide','Продолжить');return}app.innerHTML=pageTitle('Проверьте заявку','Шаг 2 из 2',`booking/${m.id}`)+`<div class="form-page"><div class="request-preview"><img class="avatar" src="${imageSrc(m.avatarFile||m.avatar,'portrait1')}" alt=""><div><strong>${esc(m.name)}</strong><p>${esc(m.role)}</p></div></div>${refImage()?`<div class="review-reference"><img src="${refImage()}" alt="Ваш ориентир"><div><small class="muted">Ваш ориентир</small><p>${esc(s.name)}</p></div></div>`:''}<div class="summary-row"><div><small>Услуга</small><strong>${esc(s.name)}</strong></div><a class="link" href="#master/${m.id}">Изменить</a></div><div class="summary-row"><div><small>Желаемая дата</small><strong>${dateText(draft.date,{weekday:'long',day:'numeric',month:'long'})}</strong></div><a class="link" href="#booking/${m.id}">Изменить</a></div><div class="summary-row"><div><small>Желаемое время</small><strong>${esc(timeText(draft))}</strong></div><a class="link" href="#booking/${m.id}">Изменить</a></div><div style="margin:21px 0"><span class="price-tag">Предварительно — ${money(s.price)}</span><p class="small muted" style="margin-top:8px">Мастер подтвердит время и стоимость. Оплаты сейчас нет.</p></div><form id="reviewForm"><div class="field"><label for="clientName">Ваше имя</label><input id="clientName" name="name" maxlength="60" autocomplete="given-name" value="${esc(draft.name||db.client.name||'')}" placeholder="Как к вам обращаться?" required></div><div class="field"><label for="clientPhone">Телефон</label><input id="clientPhone" name="phone" type="tel" inputmode="tel" autocomplete="tel" value="${esc(contact.phone||'')}" placeholder="+7 999 123-45-67" maxlength="22" required></div><label class="check-label"><input type="checkbox" name="consent" required><span>Понимаю, что это демозаявка, и согласен сохранить введённые данные на этом устройстве.</span></label>${hint('Учебный проект: используйте вымышленные данные. SMS не отправляются. Заявку можно обработать в демокабинете мастера в этом же браузере.')}${errorBox()}<div class="form-actions"><button class="primary" type="submit">Отправить заявку</button></div></form></div>`}
function sendBooking(form){const fd=new FormData(form),name=String(fd.get('name')||'').trim(),phone=String(fd.get('phone')||'');if(!name)throw Error('Введите имя');if(!C.validatePhone(phone))throw Error('Проверьте телефон: укажите от 10 до 15 цифр');if(!fd.get('consent'))throw Error('Подтвердите сохранение демозаявки');const error=C.validateWish(draft);if(error)throw Error(error);const m=master(draft.masterId),s=service(m,draft.serviceId);if(!m||!s||m.active===false)throw Error('Услуга больше недоступна. Выберите другую');if(!C.scheduleMatch(m,draft.date,draft.period,draft.time,s.duration))throw Error('Визит не помещается в рабочие часы мастера. Выберите другой день или время');const existing=draft.editingId?db.bookings.find(b=>b.id===Number(draft.editingId)):null;if(draft.editingId&&(!existing||!C.activeStatuses.includes(existing.status)))throw Error('Эта заявка уже обработана. Создайте новую.');const id=existing?.id||Date.now()+Math.floor(Math.random()*1000);const b={id,master:m.id,serviceId:s.id,serviceName:s.name,price:Number(s.price),duration:Number(s.duration),date:draft.date,period:draft.period,time:draft.time||'',name,note:draft.note||'',referenceFile:draft.referenceFile||'',referenceWork:draft.referenceWork||'',status:'pending',createdAt:new Date().toISOString()};commit(()=>{if(existing)db.bookings=db.bookings.map(x=>x.id===id?{...b,createdAt:existing.createdAt,updatedAt:new Date().toISOString()}:x);else db.bookings.unshift(b);db.client.name=name});contact.phone=phone;saveContact();draft={};saveDraft();go('visit/'+id);toast('Демозаявка сохранена. Мастер пока не подтвердил время.')}
function bookingCard(b,forStudio=false){const m=master(b.master);return `<article class="booking-card">${statusBadge(b)}<a class="person" href="#visit/${b.id}"><img class="avatar" src="${imageSrc(m?.avatarFile||m?.avatar,'portrait1')}" alt=""><div><h3>${esc(forStudio?b.name:m?.name||'Мастер')}</h3><p>${esc(b.serviceName||m?.service||'Услуга')}</p></div>${icon('arrow')}</a><p class="date-line">${dateText(b.proposal?.date||b.date)} · ${esc(b.proposal?.time||timeText(b))}</p><span class="price-tag">${b.status==='confirmed'||b.status==='completed'?'Согласовано':'Предварительно'} — ${money(b.proposal?.price??b.price)}</span>${b.status==='pending'?'<p class="muted" style="margin-top:10px">Время ещё не подтверждено</p>':''}${b.status==='proposal'?'<p class="muted" style="margin-top:10px">Мастер предложил время и стоимость. Подтвердите, если всё подходит.</p>':''}<div class="button-row">${forStudio&&['pending','proposal'].includes(b.status)?action('master-offer','Предложить время','primary',`data-id="${b.id}"`):b.status==='proposal'?action('accept-offer','Подходит','primary',`data-id="${b.id}"`):`<a href="#visit/${b.id}" class="secondary">Посмотреть заявку</a>`}${forStudio&&['pending','proposal'].includes(b.status)?action('decline-booking','Отклонить','secondary',`data-id="${b.id}"`):b.status==='proposal'?action('edit-booking','Другое время','secondary',`data-id="${b.id}"`):''}</div>${forStudio&&b.status==='confirmed'?`<div style="margin-top:12px">${action('complete-booking','Завершить демовизит','link',`data-id="${b.id}"`)}</div>`:''}</article>`}
function bookingsPage(){const active=db.bookings.filter(b=>C.activeStatuses.includes(b.status)),list=bookingTab==='active'?active:db.bookings.filter(b=>!C.activeStatuses.includes(b.status));const priority={proposal:0,pending:1,confirmed:2};list.sort((a,b)=>(priority[a.status]??3)-(priority[b.status]??3)||b.id-a.id);app.innerHTML=pageTitle('Мои записи','Демонстрационные заявки в этом браузере','home')+`<div class="segmented" style="margin-bottom:24px"><button data-action="booking-tab" data-id="active" class="${bookingTab==='active'?'active':''}">Предстоящие · ${active.length}</button><button data-action="booking-tab" data-id="history" class="${bookingTab==='history'?'active':''}">История</button></div>${list.length?`<div class="booking-grid">${list.map(b=>bookingCard(b)).join('')}</div>`:empty(bookingTab==='active'?'Пока нет активных заявок':'История пока пуста','Выберите мастера и отправьте пожелания по времени.','catalog','Найти мастера','calendar')}`}
function visitPage(id){const b=db.bookings.find(b=>b.id===Number(id)),m=b&&master(b.master);if(!b){app.innerHTML=empty('Заявка не найдена','Она могла быть создана в другом браузере.','bookings','Мои записи');return}const w=work(b.referenceWork),ref=b.referenceFile?imageSrc(b.referenceFile):w?workImage(w):b.referenceSnapshot?imageSrc(b.referenceSnapshot):null;app.innerHTML=pageTitle('Заявка к мастеру','', 'bookings')+`<article class="booking-detail"><a class="person" href="#master/${b.master}"><img class="avatar" src="${imageSrc(m?.avatarFile||m?.avatar,'portrait1')}" alt=""><div><h2>${esc(m?.name||'Мастер')}</h2><p>${esc(b.serviceName||m?.service)}</p></div></a>${ref?`<img class="detail-photo" src="${ref}" alt="Ваш ориентир для мастера">`:''}<div class="status-heading">${icon(b.status==='pending'?'clock':b.status==='confirmed'?'check':'info')}<h2>${esc(statusNames[b.status]||'Заявка')}</h2></div>${b.status==='proposal'?`<div class="notice blue"><strong>Мастер предложил</strong><p class="date-line">${dateText(b.proposal.date)} · ${esc(b.proposal.time)}</p><span class="price-tag">${money(b.proposal.price)}</span><p class="small" style="margin-top:12px">Подтвердите, если подходят и время, и стоимость.</p></div><div class="button-row">${action('accept-offer','Подходит','primary',`data-id="${b.id}"`)}${action('edit-booking','Другое время','secondary',`data-id="${b.id}"`)}</div>`:''}<div class="details-block"><small>${b.status==='confirmed'||b.status==='completed'?'Согласованная запись':'Желаемая запись'}</small><p class="date-line">${dateText(b.date,{weekday:'long',day:'numeric',month:'long'})}<br>${esc(timeText(b))}</p></div><div class="details-block"><span class="price-tag">${b.status==='confirmed'||b.status==='completed'?'Согласовано':'Предварительно'} — ${money(b.price)}</span>${['pending','proposal'].includes(b.status)?'<p class="muted">Время ещё не подтверждено.</p>':''}</div>${b.status==='confirmed'||b.status==='completed'?`<div class="details-block"><small>Место приёма</small><strong>Ставрополь, ${esc(m?.address||'Уточните у мастера')}</strong><p class="muted">Демонстрационный адрес. Не является реальным местом приёма.</p></div>`:''}<div class="details-block"><small>Клиент</small><strong>${esc(b.name)}</strong>${b.note?`<p>${esc(b.note)}</p>`:''}</div>${b.status==='declined'?'<div class="notice">Мастер не сможет принять заявку. Можно выбрать другого с теми же пожеланиями.</div>':''}<div class="button-row">${['pending','proposal','confirmed'].includes(b.status)?action('edit-booking','Изменить пожелания','link',`data-id="${b.id}"`):''}${C.activeStatuses.includes(b.status)?action('cancel-booking','Отменить заявку','link danger',`data-id="${b.id}"`):''}${b.status==='completed'&&!db.reviews.some(r=>r.booking===b.id)?action('write-review','Оставить отзыв','primary',`data-id="${b.id}"`):''}</div><a class="primary full" style="margin-top:22px" href="#bookings">К моим записям</a><div class="demo-strip">Демо: заявку можно обработать в <a class="link" href="#studio/requests?master=${b.master}">кабинете мастера</a>. Данные не отправляются другим людям.</div></article>`}
function accountPage(){app.innerHTML=pageTitle('Личный кабинет','Демонстрационные роли на одном устройстве','home')+`<div class="profile-choice"><a class="role-card" href="#account/client">${icon('user')}<h2>Я клиент</h2><p>Контакты, заявки и избранное</p></a><a class="role-card" href="#studio/requests">${icon('briefcase')}<h2>Я мастер</h2><p>Работы, услуги, заявки и документы</p></a><a class="role-card" href="#moderation">${icon('shield')}<h2>Модерация</h2><p>Учебная очередь проверки документов</p></a></div>${notice('Это переключение <strong>демонстрационных ролей</strong>, без настоящей регистрации и разграничения доступа. Все изменения видны только в этом браузере. Не загружайте реальные паспорта и личные документы.')}<div class="section"><h2>Как проверить весь сценарий</h2><ol class="note-list"><li>Отправьте демозаявку как клиент.</li><li>В кабинете выбранного мастера предложите точное время и стоимость.</li><li>Вернитесь в «Записи» и примите предложение.</li><li>В кабинете мастера завершите демовизит, затем оставьте отзыв как клиент.</li></ol></div>`}
function clientPage(){app.innerHTML=pageTitle('Кабинет клиента','Контакты и ваши действия','account')+`<div class="account-layout"><form id="clientForm" class="form-panel"><h2>Как к вам обращаться?</h2><div class="field"><label for="profileName">Имя</label><input id="profileName" name="name" value="${esc(db.client.name||'')}" maxlength="60" autocomplete="given-name" required></div><div class="field"><label for="profilePhone">Телефон</label><input type="tel" id="profilePhone" name="phone" value="${esc(contact.phone||'')}" inputmode="tel" autocomplete="tel" maxlength="22" placeholder="+7 999 123-45-67"><p class="help">Телефон сохраняется только на время сеанса вкладки. Для демо используйте вымышленный.</p></div>${errorBox()}<button type="submit" class="primary full">Сохранить</button></form><section><h2>Ваше пространство</h2><div class="management-row"><div class="management-copy"><h3>Мои записи</h3><p>${db.bookings.length} заявок в этом браузере</p></div><a href="#bookings" class="icon-button" aria-label="Открыть записи">${icon('arrow')}</a></div><div class="management-row"><div class="management-copy"><h3>Избранное</h3><p>${db.saved.length} мастеров · ${db.savedWorks.length} работ</p></div><a href="#saved" class="icon-button" aria-label="Открыть избранное">${icon('arrow')}</a></div>${draft.masterId?`<div class="management-row"><div class="management-copy"><h3>Черновик заявки</h3><p>Вы можете продолжить или собрать новый визит.</p></div><a href="#booking/${draft.masterId}" class="link blue">Продолжить</a></div>`:''}</section></div>`}
function studioPage(tab,params){if(params.get('master')&&master(params.get('master')))studioId=Number(params.get('master'));const m=master(studioId);if(!m){go('account');return}const tabs=[['requests','Заявки'],['works','Работы'],['services','Услуги'],['profile','Профиль'],['documents','Документы']];if(!tabs.some(t=>t[0]===tab))tab='requests';const pending=db.bookings.filter(b=>b.master===m.id&&['pending','proposal'].includes(b.status));app.innerHTML=`<div class="studio-shell">${pageTitle('Кабинет мастера','Демонстрационный режим','account')}<div class="studio-top"><div><strong>${esc(m.name)}</strong><p class="small muted">Изменения появятся в локальном каталоге</p></div><div class="studio-select"><label class="sr-only" for="studioMaster">Мастер для демонстрации</label><select id="studioMaster">${db.masters.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><nav class="studio-tabs" aria-label="Разделы кабинета">${tabs.map(([id,label])=>`<a class="${tab===id?'active':''}" href="#studio/${id}">${label}${id==='requests'&&pending.length?' · '+pending.length:''}</a>`).join('')}</nav><section id="studioContent"></section></div>`;const panel=$('#studioContent');if(tab==='requests'){const list=db.bookings.filter(b=>b.master===m.id).sort((a,b)=>b.id-a.id);panel.innerHTML=`<div class="stats"><div class="stat"><strong>${pending.length}</strong><span>Ждут действия</span></div><div class="stat"><strong>${list.filter(b=>b.status==='confirmed').length}</strong><span>Подтверждены</span></div><div class="stat"><strong>${m.works.length}</strong><span>Работ в профиле</span></div></div>${list.length?`<div class="booking-grid">${list.map(b=>bookingCard(b,true)).join('')}</div>`:empty('Новых заявок пока нет','Отправьте демозаявку из каталога, выбрав этого мастера.',`master/${m.id}`,'Посмотреть мой профиль','calendar')}`}
if(tab==='works'){panel.innerHTML=`<div class="section-title"><h2>Ваши работы</h2>${action('edit-work',`${icon('plus')} Добавить`,'primary',`data-master="${m.id}"`)}</div><p class="small muted">Работы связываются с услугой и содержат стоимость конкретного результата.</p><div class="studio-list">${m.works.map(w=>`<article class="management-row"><img src="${workImage(w)}" alt="${esc(w.title)}"><div class="management-copy"><h3>${esc(w.title)}</h3><p><span class="price-tag subtle">${money(w.price)}</span> · ${duration(w.duration)}</p></div><div class="button-row">${action('edit-work',icon('edit'),'icon-button',`data-master="${m.id}" data-id="${esc(w.id)}" aria-label="Изменить работу"`)}${action('delete-work',icon('trash'),'icon-button',`data-master="${m.id}" data-id="${esc(w.id)}" aria-label="Удалить работу"`)}</div></article>`).join('')}</div>`}
if(tab==='services'){panel.innerHTML=`<div class="section-title"><h2>Услуги и цены</h2>${action('edit-service',`${icon('plus')} Добавить`,'primary',`data-master="${m.id}"`)}</div><div>${m.services.filter(s=>s.active!==false).map(s=>`<article class="management-row"><div class="management-copy"><h3>${esc(s.name)}</h3><p><span class="price-tag subtle">${money(s.price)}</span> · ${duration(s.duration)} · ${s.pricing==='estimate'?'предварительно':'фиксированная цена'}</p><p>${esc(s.description)}</p></div><div class="button-row">${action('edit-service',icon('edit'),'icon-button',`data-master="${m.id}" data-id="${esc(s.id)}" aria-label="Изменить услугу"`)}${action('delete-service',icon('trash'),'icon-button',`data-master="${m.id}" data-id="${esc(s.id)}" aria-label="Убрать услугу из прайса"`)}</div></article>`).join('')}</div>`}
if(tab==='profile'){panel.innerHTML=`<form id="masterProfileForm" class="form-panel"><div class="field-row"><div class="field"><label for="masterName">Имя и фамилия</label><input name="name" id="masterName" value="${esc(m.name)}" maxlength="80" required></div><div class="field"><label for="masterRole">Специализация</label><input name="role" id="masterRole" value="${esc(m.role)}" maxlength="80" required></div></div><div class="field"><label for="masterBio">О себе</label><textarea name="text" id="masterBio" maxlength="1500" required>${esc(m.text)}</textarea></div><div class="field-row"><div class="field"><label for="masterArea">Район</label><select id="masterArea" name="area">${areas.map(a=>`<option ${m.area===a?'selected':''}>${a}</option>`).join('')}</select></div><div class="field"><label for="masterExp">Опыт</label><input name="experience" id="masterExp" value="${esc(m.experience)}" maxlength="40" required></div></div><div class="field"><label for="masterAddress">Демонстрационный адрес</label><input name="address" id="masterAddress" value="${esc(m.address)}" maxlength="150" required></div><div class="field"><label for="masterAvatar">Фото профиля, необязательно</label><input type="file" id="masterAvatar" name="avatar" accept="image/jpeg,image/png,image/webp"><p class="help">JPG, PNG или WebP, до 8 МБ</p></div><h2 style="margin:20px 0 14px">Рабочие часы</h2><div class="field-row"><div class="field"><label for="workStart">Начало</label><input name="start" id="workStart" type="time" value="${m.schedule.start}" required></div><div class="field"><label for="workEnd">Окончание</label><input name="end" id="workEnd" type="time" value="${m.schedule.end}" required></div></div><span class="small muted">Рабочие дни</span><div class="workdays">${[[1,'Пн'],[2,'Вт'],[3,'Ср'],[4,'Чт'],[5,'Пт'],[6,'Сб'],[0,'Вс']].map(([id,label])=>`<label><input name="days" type="checkbox" value="${id}" ${m.schedule.days.includes(id)?'checked':''}>${label}</label>`).join('')}</div><label class="check-label"><input type="checkbox" name="active" ${m.active!==false?'checked':''}><span>Принимаю заявки и показываюсь в каталоге</span></label>${errorBox()}<div class="form-actions"><button class="primary" type="submit">Сохранить профиль</button><a class="secondary" href="#master/${m.id}">Как видит клиент</a></div></form>`}
if(tab==='documents'){panel.innerHTML=`<div class="section-title"><h2>Образование и документы</h2>${action('upload-document',`${icon('plus')} Добавить`,'primary',`data-master="${m.id}"`)}</div>${notice('Загружайте только тестовые файлы. Они хранятся в этом браузере, без отправки на сервер. После демонстрационной проверки документ появится в локальном профиле.')}<div>${m.documents.length?m.documents.map(d=>docRow(m,d,true)).join(''):'<p class="muted">Пока нет загруженных документов.</p>'}</div><a class="link blue" href="#moderation">Открыть демоочередь модерации</a>`}}
function serviceDialog(m,id){const s=service(m,id);showDialog(s?'Изменить услугу':'Добавить услугу',`<form id="serviceForm" data-master="${m.id}" data-id="${esc(id||'')}"><div class="field"><label for="serviceName">Название</label><input id="serviceName" name="name" value="${esc(s?.name||'')}" maxlength="100" required></div><div class="field"><label for="serviceCat">Категория</label><select id="serviceCat" name="cat">${serviceCats.map(([key,label])=>`<option value="${key}" ${(s?.cat||m.cat)===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field-row"><div class="field"><label for="servicePrice">Стоимость, ₽</label><input type="number" id="servicePrice" name="price" value="${s?.price??''}" min="0" max="1000000" required></div><div class="field"><label for="serviceDuration">Длительность, мин</label><input type="number" id="serviceDuration" name="duration" value="${s?.duration||60}" min="15" max="720" step="5" required></div></div><div class="field"><label for="servicePricing">Тип стоимости</label><select id="servicePricing" name="pricing"><option value="fixed" ${s?.pricing==='fixed'?'selected':''}>Фиксированная</option><option value="estimate" ${s?.pricing==='estimate'?'selected':''}>Предварительная, уточню</option></select></div><div class="field"><label for="serviceDescription">Что входит или от чего зависит цена</label><textarea id="serviceDescription" name="description" maxlength="500" required>${esc(s?.description||'')}</textarea></div><div class="form-error" role="alert"></div><button class="primary full" type="submit">Сохранить услугу</button></form>`)}
function workDialog(m,id){const w=m.works.find(w=>w.id===id);if(!m.services.some(s=>s.active!==false)){toast('Сначала добавьте услугу');go('studio/services');return}showDialog(w?'Изменить работу':'Добавить работу',`<form id="workForm" data-master="${m.id}" data-id="${esc(id||'')}"><div class="field"><label for="workTitle">Название работы</label><input id="workTitle" name="title" value="${esc(w?.title||'')}" maxlength="100" required></div><div class="field"><label for="workService">Услуга</label><select id="workService" name="serviceId">${m.services.filter(s=>s.active!==false).map(s=>`<option value="${esc(s.id)}" ${w?.serviceId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="workPhoto">Фото результата${w?' — для замены':''}</label>${w?`<img class="preview-upload" src="${workImage(w)}" alt="Текущее фото">`:''}<input id="workPhoto" name="photo" type="file" accept="image/jpeg,image/png,image/webp" ${w?'':'required'}><p class="help">JPG, PNG, WebP · до 8 МБ</p></div><div class="field"><label for="beforePhoto">Фото «До», необязательно</label><input id="beforePhoto" name="before" type="file" accept="image/jpeg,image/png,image/webp"></div><div class="field-row"><div class="field"><label for="workPrice">Стоимость этой работы, ₽</label><input type="number" id="workPrice" name="price" value="${w?.price??''}" min="0" max="1000000" required></div><div class="field"><label for="workDuration">Длительность, мин</label><input type="number" id="workDuration" name="duration" value="${w?.duration||60}" min="15" max="720" step="5" required></div></div><div class="field"><label for="workDescription">Задача и результат</label><textarea id="workDescription" name="description" maxlength="1500" required>${esc(w?.description||'')}</textarea></div><div class="form-error" role="alert"></div><button class="primary full" type="submit">Сохранить работу</button></form>`)}
function documentDialog(m){showDialog('Добавить документ',`<form id="documentForm" data-master="${m.id}"><div class="notice demo">Для проверки интерфейса используйте вымышленные документы. Реальные паспорта и персональные данные не нужны.</div><div class="field"><label for="docTitle">Название</label><input id="docTitle" name="title" maxlength="120" placeholder="Например, сертификат об обучении" required></div><div class="field"><label for="docKind">Тип документа</label><select name="kind" id="docKind"><option>Сертификат</option><option>Диплом</option><option>Повышение квалификации</option><option>Другое</option></select></div><div class="field"><label for="docFile">Файл</label><input type="file" name="file" id="docFile" accept="application/pdf,image/jpeg,image/png,image/webp" required><p class="help">PDF, JPG, PNG, WebP · до 8 МБ. В этом браузере файл останется доступен после перезагрузки.</p></div><div class="form-error" role="alert"></div><button class="primary full" type="submit">Загрузить тестовый документ</button></form>`)}
function moderationPage(){const docs=db.masters.flatMap(m=>m.documents.map(d=>({m,d})));app.innerHTML=pageTitle('Демомодерация','Процесс проверки документов','account')+notice('Здесь можно проверить работу статусов на тестовом файле. Подлинность документов сервис не устанавливает. Доступ к этому демо не защищён аккаунтом.')+`<div>${docs.length?docs.sort((a,b)=>(a.d.status==='uploaded'?0:1)-(b.d.status==='uploaded'?0:1)).map(({m,d})=>`<section class="form-panel" style="margin:20px 0"><p class="small muted">${esc(m.name)}</p>${docRow(m,d,false)}${d.status!=='reviewed'?`<div class="button-row" style="margin-top:18px">${action('review-doc','Одобрить в демо','primary',`data-master="${m.id}" data-id="${esc(d.id)}"`)}${action('reject-doc','Вернуть с причиной','secondary',`data-master="${m.id}" data-id="${esc(d.id)}"`)}</div>`:`<p class="small muted" style="margin-top:12px">Отметка видна в локальном профиле мастера.</p>`}</section>`).join(''):empty('Очередь пуста','Добавьте тестовый документ в кабинете мастера.','studio/documents','К документам','file')}</div>`}
async function openDocument(masterId,id){const m=master(masterId),doc=m?.documents.find(d=>d.id===id);if(!doc)throw Error('Документ не найден');const file=await F.get(doc.fileId);if(!file)throw Error('Файл не найден в этом браузере. Загрузите его повторно.');const url=await ensureFileURL(doc.fileId);showDialog(doc.title,`${file.type==='application/pdf'?`<iframe class="document-viewer" title="Просмотр документа" src="${url}"></iframe>`:`<img class="document-image" src="${url}" alt="${esc(doc.title)}">`}<p class="small muted" style="margin-top:14px">Тестовый файл · ${esc(doc.name)}</p><a class="link blue" href="${url}" target="_blank" rel="noopener">Открыть в отдельной вкладке</a>`)}
function offerDialog(id){const b=db.bookings.find(b=>b.id===Number(id)),m=b&&master(b.master);if(!b||!m||!['pending','proposal'].includes(b.status))throw Error('Эта заявка уже обработана');showDialog('Предложить время и цену',`<p class="small muted" style="margin-bottom:18px">${esc(b.name)} · ${esc(b.serviceName)}<br>Просит: ${dateText(b.date)}, ${esc(timeText(b))}</p><form id="offerForm" data-id="${b.id}"><div class="field"><label for="offerDate">Дата визита</label><input type="date" id="offerDate" name="date" value="${b.proposal?.date||b.date}" min="${C.localDate()}" required></div><div class="field"><label for="offerTime">Точное начало</label><input type="time" id="offerTime" name="time" value="${b.proposal?.time||b.time||'17:00'}" required><p class="help">Рабочие часы ${m.schedule.start}–${m.schedule.end}. Визит: ${duration(b.duration)}.</p></div><div class="field"><label for="offerPrice">Стоимость, ₽</label><input type="number" id="offerPrice" name="price" min="0" max="1000000" value="${b.proposal?.price??b.price}" required></div><p class="small muted">Клиент должен согласиться и с временем, и с ценой. До этого запись не подтверждена.</p><div class="form-error" role="alert"></div><button type="submit" class="primary full" style="margin-top:22px">Отправить предложение в демо</button></form>`)}
function reviewDialog(id){const b=db.bookings.find(b=>b.id===Number(id));if(!b||b.status!=='completed')throw Error('Отзыв доступен после завершения демовизита');if(db.reviews.some(r=>r.booking===b.id))throw Error('Вы уже оставили отзыв');showDialog('Отзыв о демовизите',`<form id="reviewVisitForm" data-id="${b.id}"><div class="field"><label for="reviewRating">Ваша оценка</label><select name="rating" id="reviewRating">${[5,4,3,2,1].map(n=>`<option value="${n}">${n} ${'★'.repeat(n)}</option>`).join('')}</select></div><div class="field"><label for="reviewText">Как всё прошло?</label><textarea name="text" id="reviewText" minlength="10" maxlength="1500" required placeholder="Не менее 10 символов"></textarea></div><div class="form-error" role="alert"></div><button type="submit" class="primary full">Опубликовать демоотзыв</button></form>`)}
function editBooking(id){const b=db.bookings.find(b=>b.id===Number(id)),m=b&&master(b.master),s=m&&service(m,b.serviceId);if(!b||!C.activeStatuses.includes(b.status))throw Error('Эту заявку уже нельзя изменить');if(!s)throw Error('Услуга больше не доступна. Выберите другую в профиле');draft={...draft,masterId:b.master,serviceId:b.serviceId,cat:s.cat,date:b.date,period:b.period||'exact',time:b.time||'',note:b.note||'',name:b.name,referenceFile:b.referenceFile,referenceWork:b.referenceWork,editingId:b.id};saveDraft();go('booking/'+b.master)}
function clearClientDraft(){draft={};saveDraft()}
function setSticky(html,note=''){$('#stickyAction').innerHTML=`<div class="sticky-bar">${note?`<small>${esc(note)}</small>`:''}${html}</div>`;document.body.classList.add('has-cta');$('#bottomNav').hidden=true;document.body.classList.remove('has-nav')}
function renderNavigation(current){const attention=db.bookings.filter(b=>b.status==='proposal').length;const nav=$('#bottomNav');nav.hidden=false;nav.innerHTML=[['home','search','Поиск'],['saved','heart','Избранное'],['bookings','calendar','Записи']].map(([href,ico,label])=>`<a href="#${href}" class="${current===href?'active':''}" ${current===href?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${href==='bookings'&&attention?`<span class="badge-number">${attention}</span>`:''}</a>`).join('');document.body.classList.add('has-nav')}
function render(scroll=true){if(dialog.open)dialog.close();const raw=location.hash.slice(1)||'home',[path,query='']=raw.split('?'),params=new URLSearchParams(query),parts=path.split('/');route=parts[0];$('#stickyAction').innerHTML='';document.body.classList.remove('has-cta');renderNavigation(['saved','bookings'].includes(route)?route:'home');currentMasterId=null;document.body.classList.toggle('focus-flow',['master','work','guide','booking','review','visit'].includes(route));try{switch(route){case 'home':home();break;case 'catalog':catalog();break;case 'saved':savedPage();break;case 'master':profile(parts[1],params);break;case 'work':workPage(decodeURIComponent(parts[1]||''));break;case 'guide':guide(params);break;case 'shortlist':shortlist();break;case 'booking':bookingPage(parts[1]);break;case 'review':reviewPage();break;case 'bookings':bookingsPage();break;case 'visit':visitPage(parts[1]);break;case 'account':parts[1]==='client'?clientPage():accountPage();break;case 'studio':studioPage(parts[1]||'requests',params);break;case 'moderation':moderationPage();break;default:app.innerHTML=empty('Такого экрана нет','Вернитесь к поиску мастера.');}if(['guide','booking','review','studio','moderation'].includes(route)){$('#bottomNav').hidden=true;document.body.classList.remove('has-nav')}document.title=({home:'Форма — найдите своего мастера',guide:'Соберём ваш визит — Форма',studio:'Кабинет мастера — Форма',bookings:'Мои записи — Форма',review:'Проверьте заявку — Форма'})[route]||'Форма — бьюти-мастера';if(scroll){window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true})}}catch(e){app.innerHTML=empty('Не удалось открыть экран','Ваши сохранённые данные остались в браузере. Попробуйте вернуться к поиску.');console.error(e)}}
async function ensureFileURL(id){if(fileURLs.has(id))return fileURLs.get(id);const file=await F.get(id);if(!file)throw Error('Файл не найден на этом устройстве');const url=URL.createObjectURL(file.blob);fileURLs.set(id,url);return url}
async function hydrateFiles(){try{const files=await F.all();for(const file of files)fileURLs.set(file.id,URL.createObjectURL(file.blob))}catch(e){console.warn('Local file storage:',e.message)}}
async function storeFile(file,imageOnly){const meta=await F.put(file,imageOnly);await ensureFileURL(meta.id);return meta}
function getNumbers(form){const fd=new FormData(form),price=Number(fd.get('price')),length=Number(fd.get('duration'));if(!Number.isFinite(price)||price<0||price>1000000)throw Error('Укажите стоимость от 0 до 1 000 000 ₽');if(!Number.isFinite(length)||length<15||length>720)throw Error('Длительность должна быть от 15 до 720 минут');return {price,duration:length}}
function assertText(value,min,max,label){const text=String(value||'').trim();if(text.length<min||text.length>max)throw Error(label);return text}
async function saveMasterProfile(form){const fd=new FormData(form),m=master(studioId),days=fd.getAll('days').map(Number),start=String(fd.get('start')),end=String(fd.get('end'));if(!C.validTime(start)||!C.validTime(end)||C.minutes(start)>=C.minutes(end))throw Error('Окончание рабочего дня должно быть позже начала');if(!days.length)throw Error('Отметьте хотя бы один рабочий день');const values={name:assertText(fd.get('name'),2,80,'Укажите имя мастера'),role:assertText(fd.get('role'),2,80,'Укажите специализацию'),text:assertText(fd.get('text'),5,1500,'Добавьте описание от 5 символов'),address:assertText(fd.get('address'),3,150,'Укажите демонстрационный адрес'),experience:assertText(fd.get('experience'),1,40,'Укажите опыт'),area:String(fd.get('area')),active:fd.get('active')==='on',schedule:{days,start,end}};const file=fd.get('avatar');if(file?.size){const stored=await storeFile(file,true);values.avatarFile=stored.id}commit(()=>Object.assign(master(m.id),values));toast('Профиль сохранён');render(false)}
async function saveWork(form){const fd=new FormData(form),m=master(form.dataset.master),old=m.works.find(w=>w.id===form.dataset.id),numbers=getNumbers(form),s=service(m,String(fd.get('serviceId')));if(!s)throw Error('Выберите действующую услугу');const values={id:old?.id||'work-'+crypto.randomUUID(),title:assertText(fd.get('title'),3,100,'Добавьте название от 3 символов'),description:assertText(fd.get('description'),5,1500,'Добавьте описание от 5 символов'),serviceId:s.id,...numbers,demo:old?.demo||false};if(fd.get('photo')?.size){const file=await storeFile(fd.get('photo'),true);values.fileId=file.id;values.demo=false}else if(!old)throw Error('Добавьте фото результата');if(fd.get('before')?.size){const file=await storeFile(fd.get('before'),true);values.beforeFile=file.id}commit(()=>{const list=master(m.id).works,index=list.findIndex(w=>w.id===values.id);if(index>=0)list[index]={...list[index],...values};else list.unshift(values)});dialog.close();render(false);toast('Работа сохранена в профиле')}
async function saveDocument(form){const fd=new FormData(form),m=master(form.dataset.master);const title=assertText(fd.get('title'),3,120,'Укажите название от 3 символов');const meta=await storeFile(fd.get('file'),false);const doc={id:'doc-'+crypto.randomUUID(),fileId:meta.id,title,kind:String(fd.get('kind')),name:meta.name,type:meta.type,size:meta.size,status:'uploaded',createdAt:new Date().toISOString()};commit(()=>master(m.id).documents.unshift(doc));dialog.close();render(false);toast('Тестовый документ загружен. Он ждёт демомодерации.')}
async function handleAction(el,event){const name=el.dataset.action,id=el.dataset.id,mid=Number(el.dataset.master);switch(name){case 'category':filters={...filters,cat:id,search:''};go('catalog');break;case 'catalog-cat':filters.cat=id;catalog();break;case 'reset-filters':filters={cat:'',budget:0,area:'',search:'',sort:'recommended'};if(dialog.open)dialog.close();catalog();break;case 'filters':filtersDialog();break;case 'save-master':favoriteMaster(Number(id),el);break;case 'save-work':favoriteWork(id,el);break;case 'saved-tab':savedTab=id;savedPage();break;case 'booking-tab':bookingTab=id;bookingsPage();break;case 'start-booking':startBooking(mid,el.dataset.service);break;case 'book-work':{const w=work(id),m=w&&master(w.masterId);if(!w||!service(m,w.serviceId))throw Error('Услуга этой работы больше недоступна. Выберите другую в профиле мастера.');startBooking(m.id,w.serviceId,w.id);break}case 'work-photo':{const w=work(id);if(!w)return;$('#workDetailImage').src=el.dataset.photo==='before'?imageSrc(w.beforeFile):workImage(w);document.querySelectorAll('[data-action="work-photo"]').forEach(x=>x.classList.toggle('selected',x===el));break}case 'select-day':{const form=el.closest('form'),input=form.querySelector('[name=date]');input.value=el.dataset.date;form.querySelectorAll('.day-option').forEach(x=>{x.classList.toggle('selected',x===el);x.setAttribute('aria-pressed',String(x===el))});collectDraft(form);break}case 'select-period':{const form=el.closest('form');form.querySelector('[name=period]').value=id;form.querySelectorAll('.time-option').forEach(x=>{x.classList.toggle('selected',x.dataset.id===id);x.setAttribute('aria-pressed',String(x.dataset.id===id))});const wrap=form.querySelector('.exact-time'),input=form.querySelector('[name=time]');wrap.hidden=id!=='exact';input.disabled=id!=='exact';if(id!=='exact')input.value='';else input.focus();collectDraft(form);break}case 'remove-reference':draft.referenceFile='';draft.referenceWork='';saveDraft();if(route==='guide'){const form=$('#guideForm');if(form)collectDraft(form);guide(new URLSearchParams())}break;case 'close-dialog':dialog.close();break;case 'edit-service':serviceDialog(master(mid),id);break;case 'edit-work':workDialog(master(mid),id);break;case 'upload-document':documentDialog(master(mid));break;case 'open-doc':await openDocument(mid,id);break;case 'delete-doc':{const m=master(mid),d=m.documents.find(d=>d.id===id);if(!d)return;confirmDialog('Удалить тестовый документ?','Документ исчезнет из кабинета, демомодерации и локального профиля.',async()=>{commit(()=>{master(mid).documents=master(mid).documents.filter(x=>x.id!==id)});try{await F.remove(d.fileId);if(fileURLs.has(d.fileId)){URL.revokeObjectURL(fileURLs.get(d.fileId));fileURLs.delete(d.fileId)}}catch{toast('Документ скрыт, но файл не удалось удалить из хранилища браузера')}render(false)},'Удалить');break}case 'delete-work':confirmDialog('Удалить работу?','Она исчезнет из профиля и избранного. В уже отправленных заявках ориентир сохранится.',()=>{commit(()=>{const m=master(mid),w=m.works.find(x=>x.id===id);if(w){db.bookings.forEach(b=>{if(b.referenceWork===id&&!b.referenceFile){b.referenceSnapshot=w.fileId||w.image}})}m.works=m.works.filter(w=>w.id!==id);db.savedWorks=db.savedWorks.filter(x=>x!==id)});render(false);toast('Работа удалена')},'Удалить');break;case 'delete-service':confirmDialog('Убрать услугу из прайса?','Существующие заявки сохранят своё название и стоимость. Новые заявки на эту услугу будут недоступны.',()=>{commit(()=>{const s=master(mid).services.find(s=>s.id===id);if(s)s.active=false});render(false);toast('Услуга убрана из прайса')},'Убрать услугу');break;case 'review-doc':confirmDialog('Поставить демонстрационную отметку?','Это только тест процесса. Подлинность файла не устанавливается. Документ станет доступен в локальном профиле.',()=>{commit(()=>{const d=master(mid).documents.find(d=>d.id===id);if(!d)throw Error('Документ удалён');d.status='reviewed';d.reviewedAt=new Date().toISOString();d.reason=''});render(false);toast('Демонстрационная отметка сохранена')},'Одобрить в демо');break;case 'reject-doc':showDialog('Вернуть документ с причиной',`<form id="rejectDocumentForm" data-master="${mid}" data-id="${esc(id)}"><div class="field"><label for="rejectReason">Что нужно исправить?</label><textarea name="reason" id="rejectReason" minlength="5" maxlength="500" required placeholder="Например, текст на фото не читается"></textarea></div><div class="form-error" role="alert"></div><button type="submit" class="primary full">Вернуть мастеру</button></form>`);break;case 'master-offer':offerDialog(id);break;case 'accept-offer':{const b=db.bookings.find(b=>b.id===Number(id));if(!b)throw Error('Заявка не найдена');showDialog('Подтвердить время и стоимость?',`<p class="dialog-body-copy">${dateText(b.proposal?.date)} · ${esc(b.proposal?.time||'')}<br><span class="price-tag" style="margin-top:14px">${money(b.proposal?.price)}</span></p>`,`<button class="primary" id="acceptProposal">Подтвердить запись</button><button class="secondary" data-action="close-dialog">Пока не подтверждать</button>`);$('#acceptProposal').onclick=()=>{try{const current=db.bookings.find(b=>b.id===Number(id)),updated=C.accept(current,master(current.master),db.bookings);commit(()=>{db.bookings=db.bookings.map(x=>x.id===updated.id?updated:x)});dialog.close();render(false);toast('Демозапись подтверждена')}catch(e){toast(e.message)}};break}case 'edit-booking':editBooking(id);break;case 'cancel-booking':confirmDialog('Отменить заявку?','Она останется в истории с отметкой «Отменена».',()=>{const b=db.bookings.find(b=>b.id===Number(id));if(!b||!C.activeStatuses.includes(b.status))throw Error('Эта заявка уже обработана');commit(()=>{b.status='cancelled';b.proposal=null});render(false);toast('Заявка отменена')},'Отменить заявку');break;case 'decline-booking':confirmDialog('Отклонить заявку?','Клиент увидит, что мастер не сможет принять.',()=>{const b=db.bookings.find(b=>b.id===Number(id));if(!b||!['pending','proposal'].includes(b.status))throw Error('Заявка уже обработана');commit(()=>{b.status='declined';b.proposal=null});render(false);toast('Заявка отклонена')},'Отклонить');break;case 'complete-booking':confirmDialog('Завершить демонстрационный визит?','Это учебный переход статуса. После него клиент сможет оставить демоотзыв.',()=>{const b=db.bookings.find(b=>b.id===Number(id));if(!b||b.status!=='confirmed')throw Error('Сначала клиент должен подтвердить запись');commit(()=>{b.status='completed'});render(false);toast('Демовизит завершён')},'Завершить демовизит');break;case 'write-review':reviewDialog(id);break;}}
document.addEventListener('click',event=>{const anchor=event.target.closest('[data-section]');if(anchor){event.preventDefault();document.getElementById(anchor.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return}const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();if(el.dataset.busy)return;el.dataset.busy='1';Promise.resolve(handleAction(el,event)).catch(e=>toast(e.message)).finally(()=>{delete el.dataset.busy})});
document.addEventListener('input',event=>{const el=event.target,form=el.closest('form');if(form?.hasAttribute('data-draft'))collectDraft(form);if(form?.id==='catalogSearch'){filters.search=el.value;catalogResults()}if(form?.id==='reviewForm'){if(el.name==='name'){draft.name=el.value;saveDraft()}if(el.name==='phone'){contact.phone=el.value;saveContact()}}el.classList.remove('invalid');const error=form?.querySelector('.form-error');if(error)error.textContent=''});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='catalogBudget'){filters.budget=Number(el.value);catalogResults()}if(el.id==='catalogArea'){filters.area=el.value;catalogResults()}if(el.id==='catalogSort'){filters.sort=el.value;catalogResults()}if(el.id==='studioMaster'){studioId=Number(el.value);try{localStorage.setItem('forma-studio-master',JSON.stringify(studioId))}catch{}render(false)}if(el.name==='date'&&el.closest('[data-draft]')){const form=el.closest('form');form.querySelectorAll('.day-option').forEach(x=>{x.classList.toggle('selected',x.dataset.date===el.value);x.setAttribute('aria-pressed',String(x.dataset.date===el.value))});collectDraft(form)}if(el.id==='referenceUpload'&&el.files?.[0]){const form=el.closest('form');collectDraft(form);el.disabled=true;try{const meta=await storeFile(el.files[0],true);draft.referenceFile=meta.id;draft.referenceWork='';saveDraft();if(route==='guide')guide(new URLSearchParams());toast('Фото добавлено к пожеланиям')}finally{el.disabled=false}}}catch(e){toast(e.message)}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();const button=form.querySelector('[type=submit]');if(button?.disabled)return;if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='Сохраняем…'}const fail=message=>{const el=form.querySelector('.form-error');if(el){el.textContent=message;el.style.display='block';el.setAttribute('tabindex','-1');el.focus();el.scrollIntoView({block:'center'})}else toast(message)};try{const fd=new FormData(form);switch(form.id){case 'homeSearch':filters={...filters,cat:'',search:String(fd.get('search')||'').trim()};go('catalog');break;case 'catalogSearch':filters.search=String(fd.get('search')||'').trim();catalogResults();break;case 'filtersForm':filters={...filters,budget:Number(fd.get('budget'))||0,area:String(fd.get('area')||''),cat:String(fd.get('cat')||'')};dialog.close();catalog();break;case 'guideForm':collectDraft(form);if(!serviceCats.some(c=>c[0]===draft.cat))throw Error('Выберите услугу');if(!Number.isFinite(Number(draft.budget))||Number(draft.budget)<=0||Number(draft.budget)>1000000)throw Error('Укажите корректный бюджет');{const error=C.validateWish(draft);if(error)throw Error(error)}go('shortlist');break;case 'bookingWishForm':collectDraft(form);{const error=C.validateWish(draft);if(error)throw Error(error);const m=master(draft.masterId),s=service(m,draft.serviceId);if(!m||!s)throw Error('Услуга сейчас недоступна');if(!C.scheduleMatch(m,draft.date,draft.period,draft.time,s.duration))throw Error('Визит не помещается в рабочие часы мастера. Выберите другой день или время');}go('review');break;case 'reviewForm':sendBooking(form);break;case 'clientForm':{const name=assertText(fd.get('name'),1,60,'Введите имя'),phone=String(fd.get('phone')||'').trim();if(phone&&!C.validatePhone(phone))throw Error('Проверьте номер телефона');commit(()=>{db.client.name=name});contact.phone=phone;saveContact();toast('Контакты сохранены');break}case 'masterProfileForm':await saveMasterProfile(form);break;case 'serviceForm':{const m=master(form.dataset.master),s=service(m,form.dataset.id),numbers=getNumbers(form),values={id:s?.id||'service-'+crypto.randomUUID(),name:assertText(fd.get('name'),2,100,'Введите название услуги'),cat:String(fd.get('cat')),description:assertText(fd.get('description'),3,500,'Укажите, что входит или от чего зависит цена'),pricing:String(fd.get('pricing')),active:true,...numbers};if(!serviceCats.some(c=>c[0]===values.cat))throw Error('Выберите категорию');commit(()=>{const list=master(m.id).services,index=list.findIndex(s=>s.id===values.id);if(index>=0)list[index]=values;else list.push(values)});dialog.close();render(false);toast('Услуга сохранена');break}case 'workForm':await saveWork(form);break;case 'documentForm':await saveDocument(form);break;case 'offerForm':{const b=db.bookings.find(b=>b.id===Number(form.dataset.id));if(!b)throw Error('Заявка не найдена');const updated=C.offer(b,{date:String(fd.get('date')),time:String(fd.get('time')),price:Number(fd.get('price'))},master(b.master),db.bookings);commit(()=>{db.bookings=db.bookings.map(x=>x.id===updated.id?updated:x)});dialog.close();render(false);toast('Предложение доступно клиенту в «Записях»');break}case 'rejectDocumentForm':{const reason=assertText(fd.get('reason'),5,500,'Опишите причину, не менее 5 символов');commit(()=>{const d=master(form.dataset.master).documents.find(d=>d.id===form.dataset.id);if(!d)throw Error('Документ удалён');d.status='rejected';d.reason=reason;d.reviewedAt=null});dialog.close();render(false);toast('Причина возвращения видна мастеру');break}case 'reviewVisitForm':{const b=db.bookings.find(b=>b.id===Number(form.dataset.id));if(!b||b.status!=='completed'||db.reviews.some(r=>r.booking===b.id))throw Error('Отзыв уже опубликован или визит не завершён');const text=assertText(fd.get('text'),10,1500,'Напишите от 10 до 1 500 символов'),rating=Number(fd.get('rating'));if(rating<1||rating>5)throw Error('Выберите оценку');commit(()=>{db.reviews.push({id:crypto.randomUUID(),booking:b.id,master:b.master,name:b.name,service:b.serviceName,text,rating,createdAt:new Date().toISOString()})});dialog.close();render(false);toast('Демоотзыв опубликован в профиле мастера');break}}}catch(e){fail(e.message)}finally{if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Сохранить'}}});
$('.account-button').innerHTML=icon('user');$('.dialog-close').innerHTML=icon('close');$('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()}});
window.addEventListener('hashchange',()=>render());window.addEventListener('storage',event=>{if(event.key==='forma-state-v2'&&event.newValue){try{const newer=JSON.parse(event.newValue);if(Array.isArray(newer.masters)&&Array.isArray(newer.bookings)){db=newer;toast('Данные обновились в другой вкладке. Откройте экран заново, чтобы увидеть изменения.')}}catch{}}});
(async()=>{await hydrateFiles();render();})();
})();
